export const isMcqEditoriallyActive = (question) => !Object.hasOwn(RETIRED_MCQ_REVIEW, question.id);

export function applyMcqEditorialReview(question) {
  const review = MCQ_REVIEW[question.id];
  return review ? { ...question, ...review } : question;
}
